-- Apply a built-in preset by key. mode passes through to ImportShare
-- ("newProfile" default, or "overwrite" to write into the current profile).
function SP:ApplyPreset(key, mode, profileName)
	for _, p in ipairs(self.Presets) do
		if p.key == key then
			if not p.str then return nil, "preset has no data" end
			return self:ImportShare(p.str, mode or "newProfile", profileName or p.name)
		end
	end
	return nil, "unknown preset"
end

